  createdAt: number;
  updatedAt: number;
}

export interface ToolCall {
  id: string;
  artifactId: string;
  toolName: string;
  parameters: Record<string, unknown>;
  result?: unknown;
  error?: string;
  status: ToolCallStatus;
  startedAt: number;
  completedAt?: number;
}

export interface CreateArtifactParams {
  type: string;
  title: string;
  content?: string;
  parentId?: string;
  metadata?: Record<string, unknown>;
