  toolName: string;
  parameters?: Record<string, unknown>;
}

export interface UpdateToolCallParams {
  status?: ToolCallStatus;
  result?: unknown;
  error?: string;
}

export interface EngineSnapshot {
  artifacts: Map<string, Artifact>;
  toolCalls: Map<string, ToolCall>;
  timestamp: number;
}

