import {
  Artifact,
  ToolCall,
  CreateArtifactParams,
  UpdateArtifactParams,
  CreateToolCallParams,
  UpdateToolCallParams,
  EngineSnapshot,
} from './types';
import { IArtifactEngine } from './interfaces';

export class ArtifactEngine implements IArtifactEngine {
  private artifacts: Map<string, Artifact> = new Map();
  private toolCalls: Map<string, ToolCall> = new Map();
  private artifactSubscribers: Set<(artifacts: Artifact[]) => void> = new Set();
  private toolCallSubscribers: Set<(toolCalls: ToolCall[]) => void> = new Set();
  private idCounter: number = 0;

  private generateId(prefix: string): string {
    return `${prefix}_${++this.idCounter}_${Date.now()}`;
  }

  private notifyArtifactSubscribers(): void {
    const artifacts = this.getAllArtifacts();
    this.artifactSubscribers.forEach(callback => callback(artifacts));
  }

  private notifyToolCallSubscribers(): void {
    const toolCalls = this.getAllToolCalls();
    this.toolCallSubscribers.forEach(callback => callback(toolCalls));
  }

  // Artifact CRUD
  createArtifact(params: CreateArtifactParams): Artifact {
    const id = this.generateId('artifact');
    const now = Date.now();

    const artifact: Artifact = {
      id,
      type: params.type,
      title: params.title,
      content: params.content ?? '',
      status: 'pending',
      parentId: params.parentId ?? null,
      childIds: [],
      metadata: params.metadata ?? {},
      createdAt: now,
      updatedAt: now,
    };

    // Update parent's childIds if parentId is provided
    if (artifact.parentId) {
      const parent = this.artifacts.get(artifact.parentId);
      if (parent) {
        parent.childIds.push(id);
        parent.updatedAt = now;
      }
    }

    this.artifacts.set(id, artifact);
    this.notifyArtifactSubscribers();
    return artifact;
  }

  getArtifact(id: string): Artifact | undefined {
    return this.artifacts.get(id);
  }

  updateArtifact(id: string, updates: UpdateArtifactParams): Artifact | undefined {
    const artifact = this.artifacts.get(id);
    if (!artifact) return undefined;

    const updatedArtifact: Artifact = {
      ...artifact,
      ...updates,
      updatedAt: Date.now(),
    };

    this.artifacts.set(id, updatedArtifact);
    this.notifyArtifactSubscribers();
    return updatedArtifact;
  }

  deleteArtifact(id: string): boolean {
    const artifact = this.artifacts.get(id);
    if (!artifact) return false;

    // Recursively delete children
    for (const childId of artifact.childIds) {
      this.deleteArtifact(childId);
    }

    // Remove from parent's childIds
    if (artifact.parentId) {
      const parent = this.artifacts.get(artifact.parentId);
      if (parent) {
        parent.childIds = parent.childIds.filter(cid => cid !== id);
        parent.updatedAt = Date.now();
      }
    }

    // Delete associated tool calls
    for (const [toolCallId, toolCall] of this.toolCalls) {
      if (toolCall.artifactId === id) {
        this.toolCalls.delete(toolCallId);
      }
    }

    this.artifacts.delete(id);
    this.notifyArtifactSubscribers();
    this.notifyToolCallSubscribers();
    return true;
  }

  // Artifact queries
  getAllArtifacts(): Artifact[] {
    return Array.from(this.artifacts.values());
  }

  getRootArtifacts(): Artifact[] {
    return this.getAllArtifacts().filter(a => a.parentId === null);
  }

  getChildren(parentId: string): Artifact[] {
    const parent = this.artifacts.get(parentId);
    if (!parent) return [];
    return parent.childIds
      .map(id => this.artifacts.get(id))
      .filter((a): a is Artifact => a !== undefined);
  }

  getArtifactsByType(type: string): Artifact[] {
    return this.getAllArtifacts().filter(a => a.type === type);
  }

  getArtifactsByStatus(status: string): Artifact[] {
    return this.getAllArtifacts().filter(a => a.status === status);
  }

  // Tool call management
  createToolCall(artifactId: string, params: CreateToolCallParams): ToolCall {
    const id = this.generateId('toolcall');

    const toolCall: ToolCall = {
      id,
      artifactId,
      toolName: params.toolName,
      parameters: params.parameters ?? {},
      status: 'pending',
      startedAt: Date.now(),
    };

    this.toolCalls.set(id, toolCall);
    this.notifyToolCallSubscribers();
    return toolCall;
  }

  getToolCall(id: string): ToolCall | undefined {
    return this.toolCalls.get(id);
  }

  updateToolCall(id: string, updates: UpdateToolCallParams): ToolCall | undefined {
    const toolCall = this.toolCalls.get(id);
    if (!toolCall) return undefined;

    const updatedToolCall: ToolCall = {
      ...toolCall,
      ...updates,
    };

    // Set completedAt if status is terminal
    if (updates.status === 'complete' || updates.status === 'error') {
      updatedToolCall.completedAt = Date.now();
    }

    this.toolCalls.set(id, updatedToolCall);
    this.notifyToolCallSubscribers();
    return updatedToolCall;
  }

  getToolCalls(artifactId: string): ToolCall[] {
    return this.getAllToolCalls().filter(tc => tc.artifactId === artifactId);
  }

  getAllToolCalls(): ToolCall[] {
    return Array.from(this.toolCalls.values());
  }

  // Subscriptions
  subscribe(callback: (artifacts: Artifact[]) => void): () => void {
    this.artifactSubscribers.add(callback);
    return () => {
      this.artifactSubscribers.delete(callback);
    };
  }

  subscribeToToolCalls(callback: (toolCalls: ToolCall[]) => void): () => void {
    this.toolCallSubscribers.add(callback);
    return () => {
      this.toolCallSubscribers.delete(callback);
    };
  }

  // State management
  getSnapshot(): EngineSnapshot {
    return {
      artifacts: new Map(this.artifacts),
      toolCalls: new Map(this.toolCalls),
      timestamp: Date.now(),
    };
  }

  restore(snapshot: EngineSnapshot): void {
    this.artifacts = new Map(snapshot.artifacts);
    this.toolCalls = new Map(snapshot.toolCalls);
    this.notifyArtifactSubscribers();
    this.notifyToolCallSubscribers();
  }

  clear(): void {
    this.artifacts.clear();
    this.toolCalls.clear();
    this.idCounter = 0;
    this.notifyArtifactSubscribers();
    this.notifyToolCallSubscribers();
  }
}

