import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ArtifactEngine } from '../src/artifact-engine';
import { Artifact, ToolCall } from '../src/types';

describe('ArtifactEngine', () => {
  let engine: ArtifactEngine;

  beforeEach(() => {
    engine = new ArtifactEngine();
  });

  describe('Artifact CRUD', () => {
    it('should create an artifact with default values', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test Document',
      });

      expect(artifact.id).toMatch(/^artifact_/);
      expect(artifact.type).toBe('document');
      expect(artifact.title).toBe('Test Document');
      expect(artifact.content).toBe('');
      expect(artifact.status).toBe('pending');
      expect(artifact.parentId).toBeNull();
      expect(artifact.childIds).toEqual([]);
      expect(artifact.metadata).toEqual({});
    });

    it('should create an artifact with provided values', () => {
      const artifact = engine.createArtifact({
        type: 'code',
        title: 'Code Snippet',
        content: 'console.log("hello")',
        metadata: { language: 'javascript' },
      });

      expect(artifact.content).toBe('console.log("hello")');
      expect(artifact.metadata).toEqual({ language: 'javascript' });
    });

    it('should get an artifact by id', () => {
      const created = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const retrieved = engine.getArtifact(created.id);
      expect(retrieved).toEqual(created);
    });

    it('should return undefined for non-existent artifact', () => {
      const retrieved = engine.getArtifact('non-existent');
      expect(retrieved).toBeUndefined();
    });

    it('should update an artifact', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const updated = engine.updateArtifact(artifact.id, {
        title: 'Updated Title',
        content: 'New content',
        status: 'complete',
      });

      expect(updated?.title).toBe('Updated Title');
      expect(updated?.content).toBe('New content');
      expect(updated?.status).toBe('complete');
      expect(updated?.updatedAt).toBeGreaterThan(artifact.createdAt);
    });

    it('should return undefined when updating non-existent artifact', () => {
      const result = engine.updateArtifact('non-existent', { title: 'Test' });
      expect(result).toBeUndefined();
    });

    it('should delete an artifact', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const result = engine.deleteArtifact(artifact.id);
      expect(result).toBe(true);
      expect(engine.getArtifact(artifact.id)).toBeUndefined();
    });

    it('should return false when deleting non-existent artifact', () => {
      const result = engine.deleteArtifact('non-existent');
      expect(result).toBe(false);
    });
  });

  describe('Parent-Child Relationships', () => {
    it('should create artifact with parent', () => {
      const parent = engine.createArtifact({
        type: 'document',
        title: 'Parent',
      });

      const child = engine.createArtifact({
        type: 'section',
        title: 'Child',
        parentId: parent.id,
      });

      expect(child.parentId).toBe(parent.id);

      const updatedParent = engine.getArtifact(parent.id);
      expect(updatedParent?.childIds).toContain(child.id);
    });

    it('should get children of an artifact', () => {
      const parent = engine.createArtifact({
        type: 'document',
        title: 'Parent',
      });

      const child1 = engine.createArtifact({
        type: 'section',
        title: 'Child 1',
        parentId: parent.id,
      });

      const child2 = engine.createArtifact({
        type: 'section',
        title: 'Child 2',
        parentId: parent.id,
      });

      const children = engine.getChildren(parent.id);
      expect(children).toHaveLength(2);
      expect(children.map(c => c.id)).toContain(child1.id);
      expect(children.map(c => c.id)).toContain(child2.id);
    });

    it('should return empty array for artifact with no children', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const children = engine.getChildren(artifact.id);
      expect(children).toEqual([]);
    });

    it('should delete children when parent is deleted', () => {
      const parent = engine.createArtifact({
        type: 'document',
        title: 'Parent',
      });

      const child = engine.createArtifact({
        type: 'section',
        title: 'Child',
        parentId: parent.id,
      });

      const grandchild = engine.createArtifact({
        type: 'paragraph',
        title: 'Grandchild',
        parentId: child.id,
      });

      engine.deleteArtifact(parent.id);

      expect(engine.getArtifact(parent.id)).toBeUndefined();
      expect(engine.getArtifact(child.id)).toBeUndefined();
      expect(engine.getArtifact(grandchild.id)).toBeUndefined();
    });

    it('should remove child from parent childIds when child is deleted', () => {
      const parent = engine.createArtifact({
        type: 'document',
        title: 'Parent',
      });

      const child = engine.createArtifact({
        type: 'section',
        title: 'Child',
        parentId: parent.id,
      });

      engine.deleteArtifact(child.id);

      const updatedParent = engine.getArtifact(parent.id);
      expect(updatedParent?.childIds).not.toContain(child.id);
    });
  });

  describe('Artifact Queries', () => {
    it('should get all artifacts', () => {
      engine.createArtifact({ type: 'doc', title: 'Doc 1' });
      engine.createArtifact({ type: 'doc', title: 'Doc 2' });
      engine.createArtifact({ type: 'code', title: 'Code 1' });

      const all = engine.getAllArtifacts();
      expect(all).toHaveLength(3);
    });

    it('should get root artifacts', () => {
      const root1 = engine.createArtifact({ type: 'doc', title: 'Root 1' });
      const root2 = engine.createArtifact({ type: 'doc', title: 'Root 2' });
      engine.createArtifact({ type: 'section', title: 'Child', parentId: root1.id });

      const roots = engine.getRootArtifacts();
      expect(roots).toHaveLength(2);
      expect(roots.map(r => r.id)).toContain(root1.id);
      expect(roots.map(r => r.id)).toContain(root2.id);
    });

    it('should get artifacts by type', () => {
      engine.createArtifact({ type: 'document', title: 'Doc 1' });
      engine.createArtifact({ type: 'document', title: 'Doc 2' });
      engine.createArtifact({ type: 'code', title: 'Code 1' });

      const documents = engine.getArtifactsByType('document');
      expect(documents).toHaveLength(2);
      documents.forEach(d => expect(d.type).toBe('document'));
    });

    it('should get artifacts by status', () => {
      const artifact1 = engine.createArtifact({ type: 'doc', title: 'Doc 1' });
      engine.createArtifact({ type: 'doc', title: 'Doc 2' });
      engine.updateArtifact(artifact1.id, { status: 'complete' });

      const complete = engine.getArtifactsByStatus('complete');
      expect(complete).toHaveLength(1);
      expect(complete[0].id).toBe(artifact1.id);
    });
  });

  describe('Tool Calls', () => {
    it('should create a tool call', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const toolCall = engine.createToolCall(artifact.id, {
        toolName: 'search',
        parameters: { query: 'test' },
      });

      expect(toolCall.id).toMatch(/^toolcall_/);
      expect(toolCall.artifactId).toBe(artifact.id);
      expect(toolCall.toolName).toBe('search');
      expect(toolCall.parameters).toEqual({ query: 'test' });
      expect(toolCall.status).toBe('pending');
    });

    it('should get a tool call by id', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const created = engine.createToolCall(artifact.id, {
        toolName: 'search',
      });

      const retrieved = engine.getToolCall(created.id);
      expect(retrieved).toEqual(created);
    });

    it('should update a tool call', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const toolCall = engine.createToolCall(artifact.id, {
        toolName: 'search',
      });

      const updated = engine.updateToolCall(toolCall.id, {
        status: 'complete',
        result: { data: 'found' },
      });

      expect(updated?.status).toBe('complete');
      expect(updated?.result).toEqual({ data: 'found' });
      expect(updated?.completedAt).toBeDefined();
    });

    it('should set completedAt when status becomes error', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const toolCall = engine.createToolCall(artifact.id, {
        toolName: 'search',
      });

      const updated = engine.updateToolCall(toolCall.id, {
        status: 'error',
        error: 'Something went wrong',
      });

      expect(updated?.completedAt).toBeDefined();
    });

    it('should get tool calls for an artifact', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      engine.createToolCall(artifact.id, { toolName: 'search' });
      engine.createToolCall(artifact.id, { toolName: 'analyze' });

      const toolCalls = engine.getToolCalls(artifact.id);
      expect(toolCalls).toHaveLength(2);
    });

    it('should delete tool calls when artifact is deleted', () => {
      const artifact = engine.createArtifact({
        type: 'document',
        title: 'Test',
      });

      const toolCall = engine.createToolCall(artifact.id, {
        toolName: 'search',
      });

      engine.deleteArtifact(artifact.id);

      expect(engine.getToolCall(toolCall.id)).toBeUndefined();
    });
  });

  describe('Subscriptions', () => {
    it('should notify subscribers when artifact is created', () => {
      const callback = vi.fn();
      engine.subscribe(callback);

      engine.createArtifact({ type: 'doc', title: 'Test' });

      expect(callback).toHaveBeenCalledTimes(1);
      expect(callback).toHaveBeenCalledWith(expect.arrayContaining([
        expect.objectContaining({ title: 'Test' })
      ]));
    });

    it('should notify subscribers when artifact is updated', () => {
      const artifact = engine.createArtifact({ type: 'doc', title: 'Test' });

      const callback = vi.fn();
      engine.subscribe(callback);

      engine.updateArtifact(artifact.id, { title: 'Updated' });

      expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should notify subscribers when artifact is deleted', () => {
      const artifact = engine.createArtifact({ type: 'doc', title: 'Test' });

      const callback = vi.fn();
      engine.subscribe(callback);

      engine.deleteArtifact(artifact.id);

      expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should unsubscribe correctly', () => {
      const callback = vi.fn();
      const unsubscribe = engine.subscribe(callback);

      engine.createArtifact({ type: 'doc', title: 'Test 1' });
      expect(callback).toHaveBeenCalledTimes(1);

      unsubscribe();

      engine.createArtifact({ type: 'doc', title: 'Test 2' });
      expect(callback).toHaveBeenCalledTimes(1);
    });

    it('should notify tool call subscribers', () => {
      const artifact = engine.createArtifact({ type: 'doc', title: 'Test' });

      const callback = vi.fn();
      engine.subscribeToToolCalls(callback);

      engine.createToolCall(artifact.id, { toolName: 'search' });

      expect(callback).toHaveBeenCalledTimes(1);
    });
  });

  describe('Snapshot and Restore', () => {
